-- Phase 3 of the NPC / bestiary work, ninth book: every species among the Dark
-- Minions of Rifts Dimension Book 1: Wormwood (printed 119-138) - rows for
-- creatures (migration 074) and their attacks in stat_attacks (owner_kind
-- 'creature').
--
-- One-off data script, run once per environment. NOT a migration.
--
-- Eight rows are playable, each an already published class: the Demon Hound
-- Riders, Entrancer and Ram-Rat, which the book offers as player characters, and
-- the Demon Goblin, Morphworm, Rumbler, Shade and Sky Rider, which it discourages
-- but sets out how to play - its wording is in pools_note. The Beast Guards print
-- two blocks under one heading, so they are two rows. Every animal, the Air Fish
-- and the Worm Zombies are NPCs, and so are both Beast Guards.
--
-- NOT HERE: the Temporal Raider (printed p.136-137), whose stats the book leaves
-- to Rifts World Book Three: England; the Dark Priest, an occupation rather than a
-- species; the Unholy, Lesion, Krikton, Salome and the other Lords of Darkness,
-- and The Rock, who are named individuals.
--
-- A RIFTS BOOK: an M.D.C. creature's pool is its Main Body M.D.C.; the "in an
-- S.D.C. environment" figures and the M.D.C. by location are in pools_note. The
-- Worm Zombies print fixed attributes (I.Q. 6, P.S. 28), kept as printed.
--
-- EXTRACTED by three book-extract-workers, each given the NAMES of its species,
-- every number read off a 200 dpi render rather than the OCR cache. RECONCILED by
-- book-reconcile against the renders, row by row; its corrections are applied.
-- Every row passes creatureFormulaGaps, the grammar the endpoint rolls with.
-- description and natural_abilities are short paraphrases - no sentence is the
-- book's.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-creatures-wormwood.sql
--
-- BY CATEGORY:
--   demon (7): Air Fish, Beast Guards: Type One Guardsman (Canine), Beast Guards: Type
--     Two Guardsman (Armored), Demon Goblin, Morphworms, Rathos the Rumbler, Shade
--   animal (3): Demon Hounds, Feathered Serpents, Skelter Bats
--   humanoid (3): Demon Hound Riders, Entrancer, Ram-Rat
--   monster (1): Sky Riders
--   undead (1): Worm Zombies

INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'air-fish', 'Air Fish', 'demon', 'rifts', 0, 'Always evil, usually diabolic or miscreant', '{"IQ":"2D4+2","ME":"2D4+2","MA":"2D4","PS":"2D6+6","PP":"2D6+6","PE":"2D6+6","PB":"1D4","Spd":"3D6+12"}', NULL, NULL, '1D6x10', '5D6', '6D6', 'P.S. and P.E. are supernatural. Spd is 3D6+12 crawling/swimming through the air, but can burst-dart at 1D4x10+100 for up to six seconds once per melee. Hit Points (in an S.D.C. environment): 1D6x10, plus 1D6x10 S.D.C. P.P.E. also radiates evil magic.', NULL, 10, '{"attacks":3,"initiative":2,"strike":3,"parry":2,"dodge":6,"roll":2}', 'Automatic dodge (no attack cost). Critical strike on unmodified 19-20. +1 save vs magic, +2 save vs psionic attack, +8 save vs horror factor.', 'Track animals & humanoids 65%, wilderness survival 90%, land navigation 85%, climb 80%/70%, W.P. knife, one W.P. of choice; speaks Gobblely 75%; uses telepathy to communicate with most others.', 'Nightvision 90 ft, sees invisible, resists cold, immune to poison/disease, bio-regenerates 10 M.D.C. every four hours and a lost limb, tail or fin in four days, tracks by smell 40% and blood scent 80%, leaps 10 ft high or 15 ft long (+5 ft running), swims 90%, and floats/glides through open air like a fish, up to 1000 ft altitude.', NULL, 'Minor psionic: presence sense, sense evil, sense magic, telepathy', '3-5 ft (0.9-1.5 m) long, fish-shaped', '50-100 lbs (22-45 kg)', '60 years', 'Roams Wormwood''s wilderness in packs; also travels through open air as if swimming', 'The Unholy; Forces of Darkness', NULL, NULL, 'Piranha-like extradimensional predator that glides through open air in fast, cunning packs, serving Wormwood''s forces of darkness as attack beast and tracker.', 'Rifts Dimension Book 1: Wormwood p.119-120');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'beast-guard-canine', 'Beast Guards: Type One Guardsman (Canine)', 'demon', 'rifts', 0, 'Always evil, usually diabolic or miscreant', '{"IQ":"2D6","ME":"2D6+8","MA":"2D6","PS":"2D6+24","PP":"2D6+12","PE":"1D6+16","PB":"2D6","Spd":"3D4x10"}', NULL, NULL, '3D4x10', '6D6', NULL, 'P.S. and P.E. are supernatural. Existing characters roll all new stats when transformed. Hit Points (in an S.D.C. environment): 1D6x10, plus 2D4x10 S.D.C. P.P.E. also radiates evil magic.', NULL, 13, '{"attacks":5,"initiative":2,"strike":3,"parry":3,"dodge":2,"roll":2,"pull":2}', 'Automatic dodge (no attack cost). One extra attack at levels five and nine. +2 to pull punch and kick attack control. Critical strike from sneak attacks and on unmodified 18-20. +2 save vs all magic, +5 save vs horror factor. Weapons of silver, Millennium Tree wood, or rune weapons do double damage.', 'R.C.C. skills replace old skills: dance, sing, hunt, trap and skin animals/humanoids, wilderness survival, land navigation +15%, palming, climb, swim, W.P. sword, all at fifth level proficiency; speaks Demongogian and Gobblely at 75%, American at 98%.', 'Nightvision 90 ft, sees invisible, resists fire/cold/poison, tracks by smell 51% and blood scent 78%, recognizes a specific scent 32%, strong leaper (15 ft high or 20 ft long, doubled from a run).', NULL, NULL, '6-7 ft (1.8-2.1 m) tall, humanoid', '300-450 lbs (135-202.5 kg), all muscle', '60 years (could reach 160 if less wild and reckless)', 'Wormwood, in service to the Host as demon minions; formerly human', 'The Unholy; Forces of Darkness', NULL, NULL, 'Former human transformed by demonic blood pact into a wolf-headed, horned mega-damage brute that fights with tooth, claw, and captured blades for the Unholy.', 'Rifts Dimension Book 1: Wormwood p.121-122');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'beast-guard-armored', 'Beast Guards: Type Two Guardsman (Armored)', 'demon', 'rifts', 0, 'Always evil, usually diabolic or miscreant', '{"IQ":"3D4+2","ME":"3D4+4","MA":"2D4+2","PS":"2D6+30","PP":"1D6+14","PE":"1D6+16","PB":"4","Spd":"2D6+10"}', NULL, NULL, '1D4x100+50', '5D6', NULL, 'P.S. and P.E. are supernatural. The transformation provides all new stats. Hit Points (in an S.D.C. environment): 2D4x10, plus 1D4x100 S.D.C. P.P.E. also radiates evil magic.', NULL, 13, '{"attacks":3,"strike":4,"parry":3,"dodge":2,"roll":2,"pull":2}', 'One extra attack at levels six and nine. +2 to pull punch and kick attack control. Critical strike on unmodified 19-20. +2 save vs all magic, +5 save vs horror factor. Weapons of silver, Millennium Tree wood, or rune weapons do double damage.', 'R.C.C. skills replace old skills: dance, wilderness survival, land navigation +15%, prowl, palming, climb, swim +20%, W.P. battle axe, W.P. targeting/spear/pole-arm, W.P. sword, all at fifth level proficiency; speaks Demongogian and Gobblely at 75%, American at 98%.', 'Nightvision 90 ft, sees invisible, impervious to normal fire and cold, moderate leaper (10 ft high or long, +5 ft running start); thick natural armor plating over a turtle-like beaked head.', NULL, NULL, '7-8 ft (2.1-2.4 m) tall, humanoid', '500-600 lbs (225-270 kg), muscle and armor', '200 years', 'Wormwood, in service to the Host as demon minions; formerly human', 'The Unholy; Forces of Darkness', NULL, NULL, 'Turtle-headed, heavily armor-plated mega-damage brute from the same demonic transformation as the canine guard, but calmer, more calculating, and equally lethal.', 'Rifts Dimension Book 1: Wormwood p.122');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'demon-goblin', 'Demon Goblin', 'demon', 'rifts', 1, 'Always evil, typically diabolic or miscreant', '{"IQ":"3D4+4","ME":"2D6+8","MA":"2D6","PS":"3D6+10","PP":"2D6+13","PE":"2D6+13","PB":"2D4","Spd":"3D6"}', NULL, NULL, '6D6x2', '3D6', NULL, 'P.S. and P.E. are supernatural. Hit Points (in an S.D.C. environment): 6D6, plus 1D6x10 S.D.C. The book discourages it as a player character; it is published here as a class (demon-goblin).', NULL, 10, '{"attacks":4,"initiative":1,"strike":3,"parry":2,"dodge":2,"roll":2,"pull":2}', 'Combat attacks vary by career: 4/melee for assassins, 3/melee for thieves and spies, plus one extra attack at levels 5, 8, and 13. Stun on unmodified 19-20, critical strike on unmodified 19-20. +1 save vs magic, +2 save vs poison/disease, +4 save vs horror factor. Eyes are sensitive to bright light: must squint, halving all combat bonuses. Experience: assassin, thief, or spy - 45% second level, 20% fourth, 20% sixth, 15% eighth or higher.', 'R.C.C. skills depend on career path (Assassin, Thief, or Spy), each with its own printed list (wilderness survival, land navigation, prowl, climb, swim, streetwise, various W.P.s, etc., with percentages as printed); most speak Demongogian and Gobblely ~94%, Dragonese and American 50-70%; only a small percentage read/write.', 'Nightvision 400 ft, sees invisible, resists normal fire/cold, tunnels 70%, exceptional balance and acrobatic skills, bio-regenerates 6D6 M.D.C. up to twice an hour, capable leaper.', NULL, NULL, '3-4 ft (0.9-1.2 m) tall, humanoid', '50-100 lbs (25-45 kg)', '195 years', 'Homeworld in another dimension (half a billion under Salome''s command); roughly three million brought to Wormwood', 'Salome (worshipped as goddess and queen)', NULL, 'Player Note (book''s wording): generally NPC villains, but a GM may allow one as a renegade/traitor player character with unprincipled or anarchist alignment, starting at first or second level; hated by other demon goblins, especially if disloyal to Salome.', 'Small, vicious extradimensional goblin race, fiercely loyal to the goddess-queen Salome, working as assassins, thieves, or spies and cannibalistic toward friend and foe alike.', 'Rifts Dimension Book 1: Wormwood p.122-124');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'demon-hounds', 'Demon Hounds', 'animal', 'rifts', 0, 'Animal predator, generally unprincipled or anarchist; some are evil', '{"ME":"2D6+10","MA":"3D6","PS":"2D6+21","PP":"2D6+12","PE":"1D6+20","PB":"3D4","Spd":"4D4x10"}', NULL, NULL, '4D4x10', '4D6', NULL, 'I.Q.: printed only as ''High animal intelligence'' (no numeric value given). P.S. and P.E. are supernatural. Hit Points (in an S.D.C. environment): 2D4x10, plus 2D4x10 S.D.C. Homeworld name: Kr''talpa (pronounced Kree-talp-ah). Mates for life; 1D4 pups every eight months; reaches full maturity in one year but cannot breed until two years old.', NULL, 12, '{"attacks":4,"initiative":2,"strike":5,"parry":1,"dodge":3}', '+5 save vs horror factor, +2 save vs poison/drugs/magic, +6 save vs mind control as long as the hound''s master (rider) is present. Vulnerabilities/Penalties: not applicable.', 'R.C.C. Skills: see natural abilities (book gives no separate skill list).', 'Thick, nearly unbreakable skull, nightvision 120 ft, exceptional hearing/sight/smell, tracks by smell 65% (the invisible too) and blood scent 89%, recognizes a specific scent 65%, swims 50%, climbs 65%, balance 65%, leaps 20 ft high or 30 ft across (+20 ft running), wilderness survival 80%, land navigation 70%.', NULL, 'Special: shares a constant empathic/psionic bond with its bonded rider (the br''talb); see Demon Hound Rider R.C.C.', '8-9 ft (2.4-2.7 m) tall at the shoulder, 12 ft (3.6 m) long', '1200-1500 lbs (540-675 kg)', '45 years', 'Native to the dimension Kr''talpa; gathers in wild packs of 4D6; on Wormwood usually bonded to a br''talb rider', 'br''talb (demon hound riders); Simvan Monster Riders (instant natural affinity)', 'Sky Riders; Feathered Serpents; Skelter Bats', NULL, 'Horse-sized, tusked and horned mega-damage predator from Kr''talpa that shares an unbreakable empathic bond with its humanoid rider, hunting and fighting as one unit.', 'Rifts Dimension Book 1: Wormwood p.124-125');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'demon-hound-riders', 'Demon Hound Riders', 'humanoid', 'rifts', 1, 'Any; those allied to the Forces of Darkness are always evil or anarchist', '{"IQ":"3D6","ME":"3D6+4","MA":"3D6","PS":"4D6+8","PP":"3D6+4","PE":"4D6","PB":"3D4+3","Spd":"6D6"}', NULL, NULL, '2D4x10', '1D6', NULL, 'Natural M.D.C. is 2D4x10 plus plate body armor (standard armor: 75 M.D.C., 30 lbs, -10% prowl penalty). Hit Points (in an S.D.C. environment): 6D6, plus 6D6 S.D.C. Not given I.S.P.: the empathic link to the bonded hound is constant/automatic and needs no concentration or psychic energy. Horror Factor: none normally, 9 while wearing demon mask and armor.', NULL, NULL, '{"attacks":3,"initiative":2,"strike":2,"parry":2,"dodge":1,"roll":2,"pull":3}', 'One additional melee attack at levels 4, 7, 10, 13. Critical strike on unmodified 19-20. +4 save vs horror factor, +1 save vs psionic attack, +4 save vs mind control while the bonded hound is present. Damage varies with supernatural P.S. If the bonded hound (or its offspring) dies, rider suffers -2 to all combat bonuses and -15% skills for 1D6 hours, plus empathic headache/nausea if the hound is in pain.', 'Basic math +20%, dance +10%, sing, sewing +5%, first aid +5%, horsemanship: demon hound +16%, horsemanship: feathered serpent, horsemanship: horse +4%, pilot: sailboat, wilderness survival +10%, land navigation +10%, preserve food +10%, skin and prepare animal hides +15%, track animals +20%, W.P. sword, W.P. spear/pole-arm, two W.P.s of choice, plus four skills of choice from physical, rogue, technical, or wilderness categories. Speaks Br''talb 98%, Demongogian, Gobblely, and American 85%.', 'Nightvision 90 ft; keen eyesight, hearing, and scent tracking (25% scent, 45% blood scent, 20% recognize person, 55% recognize poison); empathic/psionic bond with a bonded demon hound sharing danger, pain, and emotion across roughly five miles per experience level.', NULL, 'Empathic/psionic bond with a bonded demon hound only; no I.S.P. required, link is automatic', '7-8 ft tall (2.1-2.4 m)', '200-300 lbs (90-135 kg, all muscle)', '100 years', 'Homeworld Br''talb; also found riding with their hounds on Wormwood', 'Bonded kr''talpa demon hounds; Unholy/Forces of Darkness (about 35%); Champions of Light (about 15%); independent mercenaries/unallied adventurers (about 50%)', 'Sky Riders; skelter bats; feathered serpents', NULL, 'Dimensional humanoid warriors psychically bonded to giant demon hounds; large, canine-toothed hunters of Wormwood who favor blade weapons and view most outsiders as prey or rivals.', 'Rifts Dimension Book 1: Wormwood p.125-126');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'entrancer', 'Entrancer', 'humanoid', 'rifts', 1, 'NPC villains: anarchist or evil. Player characters: any, typically good or selfish', '{"IQ":"3D6+2","ME":"3D6+7","MA":"3D6","PS":"3D6+6","PP":"3D6","PE":"3D6+4","PB":"1D6","Spd":"5D6"}', NULL, NULL, '1D4x100', '3D6x10', '1D4x100', 'Body armor adds 40 to 100 M.D.C. on top of the base M.D.C. Hit Points (in an S.D.C. environment): 1D4x1000.', NULL, 16, '{"attacks":3,"initiative":2,"strike":1,"parry":1,"dodge":1,"roll":2,"pull":2}', 'Three attacks by hand to hand or psionics, or two by magic; one additional melee attack at levels 5, 9, 14. Critical strike on unmodified 19-20. +7 save vs horror factor, +2 save vs most psionic attacks, +4 save vs mind control and illusions. Damage varies with supernatural P.S. -2 to save vs empathy/empathic transmission. A psychic vampire that feeds on emotions; strong emotions can trigger an involuntary reaction (percentile roll: intense anger, despair, fear, frustration, hate/berserker rage, or love/happiness), each with combat and skill modifiers lasting several melee rounds.', 'Basic and advanced math +20%, sing +10%, horsemanship +10%, wilderness survival +10%, land navigation +10%, lore: demons and monsters +20%, lore: faerie +10%, anthropology +10%, two science or technical skills of choice +10%, two piloting skills of choice, two W.P.s of choice (including modern weapons), two rogue skills of choice. Speaks Demongogian and Dragonese 98% and uses magic or telepathy to communicate.', 'Exceptional vision including infrared/ultraviolet and see-the-invisible; nightvision 90 ft; bio-regeneration 4D6 M.D.C. per minute; dimensional teleport 64%.', 'Befuddle, fear, calling, compulsion, domination, trance, memory bank, horrific illusion, multiple image, mask of deceit, tongues, plus 1D4 additional spells from each of levels 1, 2, 3, and 4', 'Mind melter (1D4x100 I.S.P.): all healing and sensitive abilities, mind block auto-defense, bio-manipulation, empathic transmission, hypnotic suggestion, mind bond, mind wipe, plus two of choice from any category', '6-7 ft tall (1.8-2.1 m)', '150-250 lbs (67.5-112.5 kg)', '500 years', 'Dimensional wanderers; some have come to Wormwood to champion the cause of humans there', 'Unholy/Forces of Darkness (about 65%); Champions of Light (about 10%); independent mercenaries/unallied adventurers (about 25%)', 'Evil entrancers hunt and slay the good/renegade minority; Most humans and Knights of the Cathedral fear and distrust them', NULL, 'Pale, one-eyed psychic-vampire humanoids who wield illusion and mind-control magic; most serve the Unholy, though a rare minority champion humans against the Forces of Darkness.', 'Rifts Dimension Book 1: Wormwood p.126-127');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'feathered-serpents', 'Feathered Serpents', 'animal', 'rifts', 0, 'Animal predator, generally anarchist or miscreant; may kill or torture for pleasure', '{"IQ":"1D4+2","ME":"2D6+12","MA":"2D6","PS":"2D6+28","PP":"2D6+14","PE":"1D6+20","PB":"1D4","Spd":"5D6+10"}', NULL, NULL, '3D4x10+100', '6D6', NULL, 'I.Q. printed as ''high animal intelligence or low human intelligence 1D4+2''; formula used is the numeric figure. Spd. is 5D6+10 crawling like a snake, or 4D6x10 flying; formula used is the crawling figure. M.D.C. by Location: Arms (4) 65 each, Hands (4) 25 each, Head (1) 125, Prehensile Tongue (1) 10, Prehensile Tail Section (1) 100, Prehensile Tail Claw (1) 50, Wings (2) 90 each, Main Body 3D4x10+100 (depleting main body or head M.D.C. kills the creature). Hit Points (in an S.D.C. environment) equal the same numbers as the M.D.C. by location.', NULL, 17, '{"attacks":6,"initiative":3,"strike":4,"parry":4,"dodge":3}', '+6 to dodge when in the air (vs +3 on the ground). +5 save vs horror factor, +3 save vs poison/drugs/magic, +2 save vs psionic attack. Damage figures include the average P.S. bonus.', 'R.C.C. Skills: see natural abilities.', 'Thick unbreakable skull, winged flight, nightvision 200 ft, keen long-range sight (but one-eyed in close combat, creating a blind spot), prehensile 6-ft tongue and clawed tail for grappling; tracks by smell 45%, blood scent 65% and sight 72%, swims 75%, climbs 60%, prowls 50%, wilderness survival 85%, land navigation 85%; four clawed hands can wield swords and clubs.', NULL, NULL, '30-50 ft long (9-15.2 m), 5-7 ft diameter (1.5-2.1 m)', '3000-6000 lbs (1350-2700 kg)', '100 years', 'Homeworld Shr''ree; ridden as flying mounts by sky riders (skr''lyr) on Wormwood', 'Sky riders/skr''lyr (rider-partners)', 'Kr''talpa demon hounds; br''talb; most other animals and humanoids, which it treats as prey', NULL, 'Giant winged serpentine predators from Shr''ree, ridden by sky riders; hunt for sport as much as food, grappling prey with a clawed prehensile tail and tongue.', 'Rifts Dimension Book 1: Wormwood p.128-129');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'morphworms', 'Morphworms', 'demon', 'rifts', 1, 'NPC villains: evil, typically evil or anarchist. Player characters (rare, renegade): cannot be better than scrupulous (anarchist or aberrant more likely)', '{"IQ":"2D6+10","ME":"2D6+10","MA":"2D6+10","PS":"3D6+10","PP":"2D6+10","PE":"3D6+10","PB":"1D4","Spd":"4D6+6"}', NULL, NULL, '1D6x100', '4D6x10', '6D6x2', 'P.B. is 1D4 in natural worm form, but can rise to a P.B. of 22 via metamorphosis. Hit Points (in an S.D.C. environment): 1D4x1000. The book discourages it as a player character; it is published here as a class (morphworm).', NULL, 16, '{"attacks":3,"initiative":3,"strike":3,"parry":3,"dodge":2,"roll":3,"pull":3}', 'One additional melee attack at levels 5, 9, 14. Critical strike on unmodified 19-20. +3 save vs most types of magic, +5 save vs illusions and shape-changing magic, +6 save vs horror factor. Damage varies with supernatural P.S. Vulnerable to madness from hunger; also greedy and deceitful. Needs to eat one human-size prey per week; skill penalty -25% by day six without food, uncontrollable feeding frenzy by day seven, can survive up to eight weeks unfed. Sluggish for 24 hours after a kill while digesting: speed, all combat bonuses, and attacks/actions per melee round halved, skills at -40%.', 'Land navigation +5%, prowl +5%, climb +10%, disguise +20%, intelligence +10%, streetwise +10%, anthropology +5%, lore: demons & monsters +10%. Speaks Demongogian, Gobblely, Dragonese, Atlantean (ancient Greek), and American at 98%; reads/writes Dragonese at 90%, runes and magic symbols at 40%. Learns two new languages per new world (+25%; 75% proficiency within two months, 90% within six).', 'Shapeshifts into humans, D-Bees, or large mammals for up to 20 minutes per hour to stalk prey; dimensional teleport 70% twice daily; nightvision 200 ft; sees invisible; swims 90% to two-mile depths; bio-regenerates 1D4x10 M.D.C. per minute, though repeated use builds feeding hunger.', '80% are low-level (1D4) practitioners, usually spell casters or shifters, rarely past 4th level ability: 2D4 spells each from levels 1-3, 1D4 spells from levels 4-5, one spell from levels 6-7, plus open dimensional portal/rift and close rift', '6D6x2 I.S.P.; limited to mind block, presence sense, empathy, death trance, and alter aura (considered a minor psionic)', '8-10 ft long (2.4-3 m)', '300-400 lbs (135-180 kg)', '2000 years', 'Experienced dimensional travelers who have visited Earth and many worlds; on Wormwood mostly allied with or serving the Unholy', 'Unholy/Forces of Darkness (about 70% on Wormwood); Champions of Light (less than 2%)', 'Prey species (humans, D-Bees, mammals); most morphworms operate as loners, avoiding others of their kind', NULL, 'Shapeshifting, dimension-hopping predators that devour humanoids with a tentacled, acid-filled body; intelligent and self-aware except during recurring hunger-driven feeding frenzies.', 'Rifts Dimension Book 1: Wormwood p.129-131');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'ram-rat', 'Ram-Rat', 'humanoid', 'rifts', 1, 'NPC villains: typically evil or anarchist, occasional anarchist/good individuals exist. Player characters (renegade/free agent): should start at first or second level', '{"IQ":"3D6","ME":"3D6","MA":"3D6","PS":"3D6+6","PP":"3D6+6","PE":"3D6+3","PB":"2D4","Spd":"2D4x10"}', NULL, NULL, '4D6x10', '3D4x10', NULL, 'M.D.C. is 4D6x10 plus possible armor (typical ram-rat armor has 75 M.D.C. and a -5% prowl penalty, though they can wear any human armor). Hit Points (in an S.D.C. environment): 4D6x100.', NULL, 12, '{"attacks":4,"initiative":2,"strike":2,"parry":3,"dodge":3,"roll":2,"pull":2}', 'One additional melee attack at levels 5, 9, 13. Critical strike on unmodified 19-20. +2 save vs most types of magic, poison, and drugs; +4 save vs horror factor. Damage (punches/kicks) varies with supernatural P.S. Can turn invisible at will and see the invisible; excellent balance 80%; can leap 15 ft (4.6 m) high or long from standing (add 10 ft/3 m from a running start).', 'Prowl +5%, climb +20%, swim +10%, intelligence +10%, streetwise +10%, basic math +20%, horsemanship +10%, wilderness survival +10%, two W.P. axe (same as blunt), W.P. sword, two W.P.s of choice (including modern weapons), two piloting skills, two rogue skills +10%, two wilderness skills of choice +10%. Speaks Demongogian and Dragonese 98% and uses magic or telepathy to communicate.', 'Dimensional teleport 45% twice per 24 hours; nightvision 400 ft; sees the invisible and can turn invisible at will; bio-regenerates 1D4x10 M.D.C. once per hour; keen senses; powerful legs for 15-25 ft leaps; 80% balance.', 'See natural abilities (no separate spell list; relies on dimensional teleport and at-will invisibility)', NULL, '6-7 ft tall (1.8-2.1 m)', '200-300 lbs (90-135 kg, all muscle)', '1000 years', 'Accompanies dimensional raiding parties dispatched by the Host; found on Wormwood', 'Unholy/Forces of Darkness (about 80%); Champions of Light (about 5%); mercenaries and freebooters (about 15%)', 'Forces of good, if the ram-rat associates with them; victims it preys on, enslaves, or sells into slavery', NULL, 'Goat-horned, rat-headed supernatural raiders who bully, enslave, and spy; favor invisibility and stealth, typically serving the dimension-raiding Host alongside the Unholy.', 'Rifts Dimension Book 1: Wormwood p.131-132');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'rathos-the-rumbler', 'Rathos the Rumbler', 'demon', 'rifts', 1, 'Evil, typically diabolic or miscreant, occasionally anarchist', '{"IQ":"3D4+6","ME":"3D4+6","MA":"3D4","PS":"3D6+30","PP":"3D6+6","PE":"3D6+10","PB":"1D4","Spd":"2D4x10"}', NULL, NULL, '1D6x100', '1D6x100', NULL, 'Hit Points (in an S.D.C. environment): 1D6x1000. P.S. and P.E. are considered supernatural. M.D.C. figure is plus armor if worn (optional). The book discourages it as a player character; it is published here as a class (rumbler).', NULL, 15, '{"attacks":4,"initiative":2,"strike":2,"parry":2,"dodge":2,"roll":3,"pull":3}', 'Stun on unmodified 19-20, critical strike on unmodified 18-20. +1 save vs most magic, +4 save vs earth warlock magic, +2 save vs poison/disease, +4 save vs horror factor.; attacks per melee: 4 (+1 at levels 6, 9, 12)', 'Land navigation (+10%), prowl (+5%), climb (+10%), swim (+20%), tracking (+5%), W.P. blunt, W.P. chain, three W.P.s of choice. Speaks Demongogian/Gobblely at 98%, Dragonese/elemental/American at 65%. Only a small percentage read/write.', 'Nightvision 400 ft, sees the invisible, impervious to normal fire (magic fire/plasma half damage), bio-regenerates 6D6 M.D.C. per melee round, regrows severed limbs in a week. Sensitive eyes halve combat bonuses in bright light, and daylight vision reaches only about 1000 ft; elementals and warlock elemental magic, magic fire included, do full damage.', 'Traditional spell magic: climb, thunder clap, breathe without air, fool''s gold, magic net, repel animals, spoil. Earth elemental magic: identify minerals, identify plants, rock to mud, crumble stone, rot wood, wither plants, wall of clay, earth rumble.', NULL, 'Eight to ten feet tall (2.4 to 3 m), bulky humanoid', '400 to 600 pounds (180 to 270 kg)', '1000 years', 'Native to a world never before contacted; brought to Wormwood and beyond by the Unholy', 'Sworn to the Unholy and the Forces of Darkness', 'Gargoyles (rivals, if they reach Rifts Earth); other monsters, giants, and dragons', NULL, 'Broad, ulcer-skinned demon warriors who worship combat, smashing foes and collecting bones as trophies; recently unleashed beyond their homeworld.', 'Rifts Dimension Book 1: Wormwood p.132-133');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'shade', 'Shade', 'demon', 'rifts', 1, 'Always evil, typically diabolic or miscreant (a player character can be any, probably selfish)', '{"IQ":"3D6+2","ME":"3D6","MA":"3D6","PS":"3D6+10","PP":"3D6+6","PE":"3D6+6","PB":"2D4","Spd":"3D6+6"}', NULL, NULL, '2D4x100', '1D4x100', '3D4x10', 'Hit Points (in an S.D.C. environment): 1D4x1000. P.S. and P.E. are considered supernatural. The book discourages it as a player character; it is published here as a class (shade).', NULL, 14, '{"attacks":3,"initiative":1,"strike":3,"parry":2,"dodge":2,"roll":3,"pull":3}', 'Stun on unmodified 19-20, critical strike on unmodified 19-20. +1 save vs all magic, +2 save vs poison/disease, +5 save vs horror factor.; attacks per melee: 3 (+1 at levels 4, 8, 12)', 'Detect ambush, detect concealment (+5%), intelligence (+6%), streetwise (+10%), swim (+10%), prowl (+5%), basic math (+25%), horsemanship (+10%), wilderness survival (+10%), W.P. knife, W.P. sword, three W.P.s of choice, two piloting skills, two rogue skills (+10%), three science or technical skills (+10%). Speaks and reads Demongogian and Dragonese at 98%.', 'Dimensional teleport 65%, nightvision 1200 ft, sees invisible, turns invisible in darkness/shadow, resists normal fire/cold, impervious to poison/disease and vampire bite/mind control, bio-regenerates 1D4x10 M.D.C. a minute, instantly senses vampires on sight. Vulnerable: light-sensitive eyes halve its combat bonuses in bright light; light energy (lasers, lightning) does double damage, and a magic sphere of light holds it off as it does a vampire.', 'Shadow meld, energy disruption, escape, tongues, fly, fly as the eagle', 'Major psionic: mind block, telepathy, death trance, levitation, impervious to fire, impervious to ectoplasm', 'Six feet tall (1.8 m), humanoid', '170 to 200 pounds (76.5 to 90 kg)', '4000 years', 'Travels the Megaverse; has visited many planets including Earth', '80% sworn to the Unholy and the Forces of Darkness; 15% mercenaries and freebooters', 'Vampires', NULL, 'Cunning, stealthy demon spies and commanders with shadow-melding and psionic powers, physically marked by a fanged, jack-o-lantern-like head.', 'Rifts Dimension Book 1: Wormwood p.133-134');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'skelter-bats', 'Skelter Bats', 'animal', 'rifts', 0, 'Animal predator, generally the equivalent of anarchist or miscreant alignment', '{"ME":"2D6+10","MA":"1D6","PS":"2D6+28","PP":"2D6+10","PE":"2D4+20","PB":"1D4","Spd":"2D4x10"}', NULL, NULL, '3D4x10+150', '6D6', NULL, 'I.Q.: average animal intelligence (not a rollable formula). Spd is 2D4x10 crawling like an insect, or 4D4x10 flying. M.D.C. by Location: Legs (6) 45 each, Head (1) 150, Horns (2) 50 each, Prehensile Tail Section (1) 200, Wings (2) 90 each; Main Body 3D4x10+150 (destroying it kills the creature; destroying the head is also fatal). Hit points in an S.D.C. environment equal the same numbers as the M.D.C. by location. P.S. and P.E. are considered supernatural.', NULL, 15, '{"attacks":4,"initiative":3,"strike":4,"parry":3,"dodge":4}', '+5 save vs horror factor, +4 save vs poison/drugs/disease, +2 save vs magic.; dodge: +4 on the ground, +6 in the air or on a ceiling', 'See natural abilities.', 'Thick skull resists knockout; prehensile tail coils and entangles; winged flight; excellent hearing and vision including thermo-imaging; tracks by thermo-imaging 75%, by smell 55% and blood scent 82%; climbs 94% (walls and ceilings); swims 50%; prowl 45%, wilderness survival 90%, land navigation 55%.', NULL, NULL, '20 to 30 feet (6 to 9 m) long, stands seven feet (2.1 m) tall', '2000 to 4000 pounds (900 to 1800 kg)', '90 years', 'Homeworld Dr''myr; on Wormwood used to guard crawling towers, cathedrals, and caves', 'Sky riders (skr''lyr) as riders/handlers', 'Kr''talpa hounds; Br''talb', NULL, 'A giant six-legged, winged predator with a demonic bull-horned head and armored, serpentine body, used as a mount and guard animal.', 'Rifts Dimension Book 1: Wormwood p.134-135');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'sky-riders', 'Sky Riders', 'monster', 'rifts', 1, 'Always diabolic, miscreant, or anarchist; the best a player character can be is anarchist', '{"IQ":"3D4+1","ME":"3D4+3","MA":"3D4+1","PS":"3D6+14","PP":"2D6+10","PE":"2D6+10","PB":"3D4","Spd":"4D6"}', NULL, NULL, '2D4x10', '2D6', NULL, 'Hit Points (in an S.D.C. environment): 6D6, plus 1D6x10 S.D.C. Horror Factor is 8 on foot or 15 when riding a skelter bat or feathered serpent (8 used as the base horror_factor). P.S. and P.E. are considered supernatural. The book discourages it as a player character; it is published here as a class (sky-rider).', NULL, 8, '{"attacks":4,"initiative":1,"strike":3,"parry":1,"dodge":1,"roll":5,"pull":1}', 'Stun on unmodified 19-20, critical strike on unmodified 19-20. +1 save vs all magic, +2 save vs psionic attack, +2 save vs poison/disease, +4 save vs horror factor.; attacks per melee: 4 (+1 at levels 5, 8, 12)', 'Basic math (+5%), dance (+15%), horsemanship: skelter bat and feathered serpent (+16%), horsemanship: other large flying creature (+8%), horsemanship: horse, wilderness survival (+10%), land navigation (+15%), preserve food (+5%), skin and prepare animal hides (+10%), track animals (+15%), W.P. sword, W.P. chain, two of choice, plus four skills of choice (physical, rogue, technical, wilderness, or domestic). Speaks Skr''lyr 98%, Demongogian/Gobblely/American at 80%.', 'Keen hawk-like vision, double-jointed, ambidextrous, balance 92%, tightrope 84%, back flip 86%, climb rope 88%, leaps 10 ft; fearless and reckless only while mounted, otherwise cowardly.', NULL, NULL, 'Six to seven feet tall (1.8 to 2.1 m), humanoid', '150 to 220 pounds (67.5 to 99 kg)', '90 years', 'Homeworld Skr''lyr; ride skelter bats and feathered serpents on Wormwood', '80% sworn to the Unholy and the Forces of Darkness; 20% unallied bandits and adventurers', 'Humans and br''talb demon hound riders (frequent prey of the unallied 20%)', NULL, 'Reckless, cowardly-on-foot demon riders who become fearless daredevils on winged mounts, favoring grappling hooks and chain weapons in aerial combat.', 'Rifts Dimension Book 1: Wormwood p.135-136');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'worm-zombies', 'Worm Zombies', 'undead', 'rifts', 0, 'Always diabolic', '{"IQ":"6","ME":"N/A","MA":"N/A","PS":"28","PP":"13","PE":"N/A","PB":"1","Spd":"1D6+10"}', NULL, NULL, '2D4x10+40', '1D6x10', NULL, 'I.Q. is printed as ''roughly equal to 6, but only follows orders and kills anybody it does not recognize'' - the number 6 is used as the formula, the behavior noted here. Hit Points (in an S.D.C. environment): 2D4x10, plus 40 S.D.C. from the armor (A.R. 16). P.S. is considered supernatural.', NULL, 11, '{"attacks":3,"strike":5,"parry":4,"dodge":3,"roll":1,"pull":1}', 'Critical strike on unmodified 19-20. +2 save vs all magic. Cold and/or water halve speed and cost one melee attack. Weapons made of magic or silver inflict double damage.', 'Understand Demongogian and Gobblely at 98%, American at 75%.', 'Nightvision 200 ft, sees invisible, resists fire/cold, impervious to mind control, empathic transmission, horror factor, pain, poison, drugs, gases, and disease; bio-regenerates and regrows lost limbs unless the head is decapitated, smashed, and burned.', NULL, NULL, 'Nine feet tall (2.7 m); a humanoid skeleton covered in giant worms, wearing large shoulder pads and body armor', '300 pounds (135 kg)', 'Indefinite until destroyed; 1000+ years', 'Created by the Host''s dark magic on Wormwood', '100% loyal to the Unholy and the Forces of Darkness', NULL, NULL, 'Mindless zombie soldiers made from dead humans fused with symbiotic mystic worms, animated by dark magic and trapped life-force energy.', 'Rifts Dimension Book 1: Wormwood p.137-138');

