-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 15 creatures are in' AS assertion, count(*) AS got, 15 AS want
  FROM creatures WHERE slug IN ('air-fish', 'beast-guard-canine', 'beast-guard-armored', 'demon-goblin', 'demon-hounds', 'demon-hound-riders', 'entrancer', 'feathered-serpents', 'morphworms', 'ram-rat', 'rathos-the-rumbler', 'shade', 'skelter-bats', 'sky-riders', 'worm-zombies');
SELECT 'and their 38 attacks' AS assertion, count(*) AS got, 38 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('air-fish', 'beast-guard-canine', 'beast-guard-armored', 'demon-goblin', 'demon-hounds', 'demon-hound-riders', 'entrancer', 'feathered-serpents', 'morphworms', 'ram-rat', 'rathos-the-rumbler', 'shade', 'skelter-bats', 'sky-riders', 'worm-zombies');

